out=[]
# A few entries intentionally span adjacent verses; keep their exact Quran text together.
ranges = {(23, 97): 98, (14, 40): 41, (26, 83): 84, (60, 4): 5}
for kind,title,text,ref,s,n in quran_items:
 end = ranges.get((s,n))
 actual = ' '.join(ayah.get((s,k), '') for k in range(n, (end or n) + 1)).strip()
 if not actual:
  actual = text
 out.append({'id':f'q-{s}-{n}-{len(out)}','category':'quran','title':title,'text':actual,'source':'القرآن الكريم','reference':ref,'surah':s,'ayah':n})
for i,(cat,title,text,ref) in enumerate(hadith_items):
 out.append({'id':f'h-{i+1}','category':cat,'title':title,'text':text,'source':'السنة النبوية','reference':ref})

# Keep a transparent source note for the app's Sources screen and future updates.
(ROOT/'assets/data/duas.json').write_text(json.dumps({'version':1,'items':out},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('wrote',len(out),'items')
